/**
 * SVG icon paths mirrored from the dsh web UI (dsh-client-ui-primitives,
 * 16px outline set) so the message action row matches the browser client.
 * Each icon is one or more path data strings in a 16x16 viewBox.
 */
/** One path of an icon: bare data string, or data plus per-path attributes. */
export interface IconPath {
  readonly d: string
  readonly transform?: string
  readonly opacity?: string
  /**
   * Stroke icon path（官方 stroke 型图标，如 IconAlarmClockOutline16）：
   * 设了则按描边渲染（stroke=currentColor、不填色，fill 继承 svg 的 none）；
   * 未设走既有 fill=currentColor 填色路径。
   */
  readonly strokeWidth?: string
  readonly strokeLinecap?: string
  readonly strokeLinejoin?: string
}

export interface IconDef {
  readonly paths: readonly (string | IconPath)[]
  /** Defaults to '0 0 16 16'. */
  readonly viewBox?: string
  readonly fillRule?: "evenodd"
}

